import {ScoreQueue} from './score-queue.js';
const $=id=>document.getElementById(id);
const escape=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const playerAccount={player:null,token:null,session:null,onPlayer:null,ready:null,boardRequest:0,sample:null,
 async api(path,data={},keepalive=false){const response=await fetch('/api/'+path,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({playerToken:this.token,...data}),keepalive,signal:AbortSignal.timeout(7000)});let value;try{value=await response.json();}catch{throw Error('Player profiles need the Potatoman game server on this host.');}if(!response.ok)throw Object.assign(Error(value.error||'Could not reach player services.'),{status:response.status});return value;},
 showPlayer(){if(!this.player)return;$('playerName').value=this.player.name;$('playerMotto').value=this.player.motto;$('profileButton').textContent=this.player.name.toUpperCase();this.onPlayer?.(this.player);},
 async requirePlayer(action){await this.ready;if(this.player)return true;this.afterSave=action;$('profileStatus').textContent='Add your real name so friends can find you on the scoreboard.';$('profileDialog').showModal();$('playerName').focus();return false;},
 async refresh(){if(!this.token)return;let data;try{data=await this.api('player/get');}catch(e){if(e.status===401){this.token=null;this.player=null;try{localStorage.removeItem('potatoman.player.access');}catch{}}throw e;}this.player=data.player;this.showPlayer();const s=data.stats;$('profileStats').innerHTML=[['Best score',s.bestScore??'—'],['Rounds played',s.rounds],['Round wins',s.wins],['Knockouts',s.knockouts]].map(([label,value])=>`<div><strong>${value}</strong><span>${label}</span></div>`).join('');},
 async save(){const button=$('saveProfile');button.disabled=true;$('profileStatus').textContent='Saving your player…';try{const data=await this.api('player/save',{name:$('playerName').value,motto:$('playerMotto').value});this.player=data.player;this.token=data.playerToken;try{localStorage.setItem('potatoman.player.access',this.token);}catch{}this.showPlayer();$('profileStatus').textContent='Player saved. Every session counts, even if you leave a round early.';this.refresh().catch(()=>{});const next=this.afterSave;this.afterSave=null;if(next){$('profileDialog').close();next();}return true;}catch(e){$('profileStatus').textContent=e.message;return false;}finally{button.disabled=false;}},
 begin(level,duration,mode,circuitId,remix=false){if(this.session?.circuitId===circuitId)return;if(!this.session?.final)this.finish(false);if(!this.player||!this.token)return;this.session={run:crypto.randomUUID(),token:this.token,start:{level,duration,mode},circuitId,remix,rounds:0,wins:0,score:0,points:0,playedMs:0,knockouts:0,times:[],seen:new Set(),revision:0,final:false};},
 updateTotal(score,knockouts,points,played){const s=this.session;if(!s||s.final)return;s.score=Math.max(s.score,score??0);s.knockouts=Math.max(s.knockouts,knockouts??0);s.points=Math.max(s.points,Math.floor(points??0));s.playedMs=Math.max(s.playedMs,Math.round((played??0)*1000));},
 record({epoch,level,won,total,best,knockouts,rankedMaze=true}){const s=this.session;if(!s||s.seen.has(epoch)||s.final)return;s.seen.add(epoch);s.rounds++;s.wins+=won?1:0;s.score=Math.max(s.score,total);s.knockouts=Math.max(s.knockouts,knockouts??0);if(!s.remix&&rankedMaze&&[1,4,8,9].includes(level)&&Number.isFinite(best))this.raceTime(level,best);},
 raceTime(level,best){const s=this.session;if(!s||s.remix||!Number.isFinite(best)||![1,4,8,9].includes(level))return;const t=s.times.find(t=>t.level===level),milliseconds=Math.round(best*1000);if(t)t.milliseconds=Math.min(t.milliseconds,milliseconds);else s.times.push({level,milliseconds});},
 checkpoint(keepalive=false,final=false){this.sample?.();const s=this.session;if(s&&(!s.final||final)&&(s.playedMs>0||s.rounds>0)){s.final||=final;const payload={revision:++s.revision,score:s.score,points:s.points,playedMs:s.playedMs,rounds:s.rounds,wins:s.wins,knockouts:s.knockouts,times:s.times,final:s.final};this.queue.put({run:s.run,token:s.token,start:s.start,payload});}return this.flush(keepalive);},
 async flush(keepalive=false){if(!this.queue)return;try{await this.queue.flush(keepalive);$('scoreSaveStatus').textContent=Object.keys(this.queue.items).length?'New progress queued for saving.':'Progress saved · every session counts.';}catch{$('scoreSaveStatus').textContent='Score queued on this device. Retrying when connected.';}},
 finish(){return this.checkpoint(false,true);},
 async leaderboard(){this.checkpoint();const request=++this.boardRequest,kind=$('leaderboardKind').value,mode=$('leaderboardMode').value;$('leaderboardStatus').textContent='Loading scores…';$('leaderboardRows').innerHTML='';try{await this.flush();const {rows}=await this.api('scores/leaderboard',{...(kind==='circuit'?{}:{level:Number(kind)}),...(mode==='all'?{}:{mode})});if(request!==this.boardRequest)return;$('leaderboardStatus').textContent=rows.length?'':kind==='circuit'?'No scores yet. Play any level to put your name here.':'No escape times yet. Complete this maze to put your name here.';let rank=0,last=null;$('leaderboardRows').innerHTML=rows.map((r,i)=>{const value=kind==='circuit'?r.score:r.milliseconds;if(value!==last)rank=i+1;last=value;return`<tr${r.id===this.player?.id?' class="your-score"':''}><td>${rank}</td><td><strong>${escape(r.name)}</strong>${r.motto?`<small>${escape(r.motto)}</small>`:''}</td><td>${kind==='circuit'?r.score+' pts':(r.milliseconds/1000).toFixed(2)+'s'}</td></tr>`;}).join('');}catch(e){if(request===this.boardRequest)$('leaderboardStatus').textContent=e.message;}}
};
export function initializeProfiles(onPlayer){playerAccount.onPlayer=onPlayer;let storage;try{storage=localStorage;playerAccount.token=storage.getItem('potatoman.player.access');}catch{}playerAccount.queue=new ScoreQueue(storage,(...args)=>playerAccount.api(...args));
 $('profileButton').onclick=()=>{playerAccount.afterSave=null;$('profileDialog').showModal();playerAccount.refresh().catch(e=>$('profileStatus').textContent=e.message);};$('saveProfile').onclick=()=>playerAccount.save();$('profileDialog').addEventListener('close',()=>{playerAccount.afterSave=null;});
 const open=()=>{$('leaderboardDialog').showModal();playerAccount.leaderboard();};$('leaderboardButton').onclick=open;$('resultLeaderboard').onclick=open;$('leaderboardKind').onchange=$('leaderboardMode').onchange=$('refreshLeaderboard').onclick=()=>playerAccount.leaderboard();
 playerAccount.ready=playerAccount.refresh().catch(()=>{});playerAccount.flush();setInterval(()=>playerAccount.checkpoint(),5000).unref?.();addEventListener('online',()=>playerAccount.checkpoint());addEventListener('pagehide',()=>playerAccount.checkpoint(true));document.addEventListener('visibilitychange',()=>{if(document.hidden)playerAccount.checkpoint(true);});
}
